// ============================================================
// GET /v2/storage/create/volume 后置脚本
// 解析返回 → 写入模块变量 → 供后续 POST 创建卷使用
// ------------------------------------------------------------
// 遵循 POSTMAN_SCRIPT_STANDARDS.md 中的强制规范：
//   1. 每次执行必须先清理旧的同前缀变量
//   2. 有值就 set，没值就 unset，不允许残留空字符串或 0
//   3. 变量按业务字段命名，不依赖数组下标
// ============================================================

const res = pm.response.json();
const data = res.data || res;

// ------------------------------------------------------------
// 小工具：有值就 set，否则 unset，避免残留空变量
// ------------------------------------------------------------
function setOrUnset(key, val) {
    if (val === undefined || val === null || val === '' || Number.isNaN(val)) {
        pm.moduleVariables.unset(key);
    } else {
        pm.moduleVariables.set(key, val);
    }
}

// ============================================================
// 0. 清理所有旧的 cv_ 变量（动态扫描，防止残留）
// ============================================================
const allModuleVars = pm.moduleVariables.toObject();
Object.keys(allModuleVars)
    .filter(k => k.startsWith('cv_'))
    .forEach(k => pm.moduleVariables.unset(k));

// ============================================================
// 1. 响应合法性校验
// ============================================================
pm.test('响应结构正确', () => {
    pm.expect(res).to.be.an('object');
    pm.expect(data).to.have.property('free_disk');
    pm.expect(data).to.have.property('free_pool');
    pm.expect(data).to.have.property('hype_lock');
    pm.expect(data.free_disk).to.be.an('array');
    pm.expect(data.free_pool).to.be.an('array');
});

// ============================================================
// 2. 空闲磁盘列表 → 提取 name 和设备路径
// ============================================================
const freeDisks = (data.free_disk || []).map(d => ({
    label: `${d.name}(${d.device || ''})`,   // 下拉框显示：HDD6(/dev/sdf)
    value: (d.device || '').trim(),           // 实际值：/dev/sdf（.trim 防 %20）
    name:  (d.name  || '').trim(),            // 名称：HDD6
    capacity: d.capacity || '',               // 容量：1.00 TB
    type: d.type || '',                       // 类型：normal/ssd/nvme
    status: d.status || '',                   // 状态
}));

// 磁盘列表本身如果为空数组，也不写入（严格遵守"没值就 unset"）
if (freeDisks.length > 0) {
    pm.moduleVariables.set('cv_disk_list', JSON.stringify(freeDisks));
}

// 前 3 块空闲磁盘的路径 / 名称，供 POST 创建卷时选用
// 有几个写几个，没有就 unset
setOrUnset('cv_disk_0_path', freeDisks[0]?.value);
setOrUnset('cv_disk_0_name', freeDisks[0]?.name);
setOrUnset('cv_disk_1_path', freeDisks[1]?.value);
setOrUnset('cv_disk_1_name', freeDisks[1]?.name);
setOrUnset('cv_disk_2_path', freeDisks[2]?.value);
setOrUnset('cv_disk_2_name', freeDisks[2]?.name);

// ============================================================
// 3. 每个存储池按实际名称生成独立变量
// ============================================================
const freePools = (data.free_pool || []).map(p => ({
    label: `${p.name}(${(p.free?.value || 0).toFixed(0)}${p.free?.unit || 'KB'}可用)`,
    value: (p.name || '').trim(),
    uuid: p.uuid || '',
    free: p.free?.value || 0,
    unit: p.free?.unit || 'KB',
    total: p.total?.value || 0,
    level: p.level || '',
    lv_count: p.lv_count || 0,
}));

if (freePools.length > 0) {
    pm.moduleVariables.set('cv_pool_list', JSON.stringify(freePools));
}

// 按实际池名生成变量，如 cv_vg0_name、cv_vg2_free_gb
// 不管池编号是否连续（vg0、vg2、vg5），都能准确对应
freePools.forEach(p => {
    const poolName = p.value;                             // 如 "vg0"
    if (!poolName) return;                                // 池名空则跳过
    pm.moduleVariables.set(`cv_${poolName}_name`,    poolName);
    pm.moduleVariables.set(`cv_${poolName}_free_kb`, p.free);
    pm.moduleVariables.set(`cv_${poolName}_free_gb`, Math.floor(p.free / 1024 / 1024));
});

// 选中池默认取第一个（POST 的 device 和 pool_free_size 用这个）
// 没有可用池就 unset，绝不留空字符串
if (freePools.length > 0) {
    setOrUnset('cv_selected_pool_name',    freePools[0].value);
    setOrUnset('cv_selected_pool_free_gb', Math.floor(freePools[0].free / 1024 / 1024));
} else {
    pm.moduleVariables.unset('cv_selected_pool_name');
    pm.moduleVariables.unset('cv_selected_pool_free_gb');
}

// ============================================================
// 4. 自动生成的存储池名（mode=0 新池时用）
// ============================================================
const poolInfo = data.pool_info || {};
setOrUnset('cv_new_pool_name', poolInfo.show_name || poolInfo.uuid);
setOrUnset('cv_new_pool_sort', poolInfo.sort);

// ============================================================
// 5. 自动生成的卷名（前端回显用, 实际创建时不需要）
// ============================================================
setOrUnset('cv_new_volume_sort', data.volume_info1?.sort || data.volume_info2?.sort);

// ============================================================
// 6. 是否支持 xfs 文件系统
// hype_lock = true  → 系统中还没有 xfs 卷，可以创建 xfs
// hype_lock = false → 已有 xfs 卷，不能再选 xfs
// ============================================================
const xfsAvailable = !!data.hype_lock;
pm.moduleVariables.set('cv_xfs_available', xfsAvailable);   // 布尔值本身有意义，直接 set
const fsOptions = ['btrfs', 'ext4'];
if (xfsAvailable) fsOptions.push('xfs');
pm.moduleVariables.set('cv_fs_options', JSON.stringify(fsOptions));
pm.moduleVariables.set('cv_filesystem', 'btrfs');

// ============================================================
// 7. 调试输出
// ============================================================
console.log('==== 创建卷资源一览 ====');
console.log(`空闲磁盘: ${freeDisks.length} 块 → ${freeDisks.map(d => d.label).join(', ') || '无'}`);
console.log(`可选存储池: ${freePools.length} 个 → ${freePools.map(p => p.label).join(', ') || '无'}`);
freePools.forEach(p => {
    console.log(`  cv_${p.value}_name=${p.value}, 剩余=${Math.floor(p.free/1024/1024)}GB`);
});
console.log(`选中池: cv_selected_pool_name=${pm.moduleVariables.get('cv_selected_pool_name') || '(未设置)'}`);
console.log(`自动池名: ${poolInfo.show_name || '(未返回)'}`);
console.log(`xfs 可用: ${xfsAvailable}`);
console.log(`文件系统选项: ${fsOptions.join('/')}`);

// GET /v2/storage/edit/volume/:uuid 后置脚本
// 按卷名生成 {卷名}_mnt_path，空就删

const data = pm.response.json().data;

const mntPath = data.mntpath || '';

console.log('卷名:', data.name);
console.log('挂载路径:', mntPath);

if (mntPath) {
    pm.environment.set(`${data.name}_mnt_path`, mntPath);
    console.log(`已设置 ${data.name}_mnt_path = ${mntPath}`);
} else {
    pm.environment.unset(`${data.name}_mnt_path`);
    console.log(`已删除 ${data.name}_mnt_path`);
}

// ============================================================
// GET /v2/storage/list/storagePool 后置脚本
// 按池名生成模块变量：
//   avail_{池名}_uuid    → 可用池 UUID
//   corrupt_{池名}_uuid  → 损坏池 UUID
// 每次执行自动刷新，不存在的变量自动删除，不留遗留
// ============================================================

const pools = pm.response.json().data || {};

const availNames = [];
const corruptNames = [];

Object.values(pools).forEach(p => {
    if (p.is_available || p.health === 999) {
        availNames.push(p.name);
        pm.moduleVariables.set(`avail_${p.name}_uuid`, p.uuid);
    } else if (p.health === 0) {
        corruptNames.push(p.name);
        pm.moduleVariables.set(`corrupt_${p.name}_uuid`, p.uuid);
    }
});


// 清理已不存在的变量
const allVars = pm.moduleVariables.toObject();
Object.keys(allVars).forEach(key => {
    const am = key.match(/^avail_(.+)_uuid$/);
    const cm = key.match(/^corrupt_(.+)_uuid$/);
    if (am && !availNames.includes(am[1])) pm.moduleVariables.unset(key);
    if (cm && !corruptNames.includes(cm[1])) pm.moduleVariables.unset(key);
});


// ============================================================
// 控制台输出结果
// ============================================================
console.log('========== 存储池变量同步结果 ==========');
console.log(`可用池(${availNames.length}): ${availNames.map(n => `avail_${n}_uuid`).join(', ') || '无'}`);
console.log(`损坏池(${corruptNames.length}): ${corruptNames.map(n => `corrupt_${n}_uuid`).join(', ') || '无'}`);

// 逐个打印变量名 = 值，便于核对
console.log('---------- 可用池变量明细 ----------');
availNames.forEach(n => {
    const key = `avail_${n}_uuid`;
    console.log(`${key} = ${pm.moduleVariables.get(key)}`);
});

console.log('---------- 损坏池变量明细 ----------');
corruptNames.forEach(n => {
    const key = `corrupt_${n}_uuid`;
    console.log(`${key} = ${pm.moduleVariables.get(key)}`);
});
console.log('=======================================');

/**
 * ==========================================================
 * 功能：同步存储池 RAID设备到模块变量
 * ==========================================================
 *
 * 【脚本目的】
 *
 * 获取当前存储池对应的RAID设备：
 *
 *      pvs
 *      raidname（从 volumes 中提取）
 *
 * 自动生成模块变量：
 *
 *      vg0_raid
 *      vg1_raid
 *      vg2_raid
 *
 *      vg0_md
 *      vg1_md
 *      vg2_md
 *
 *
 * 示例：
 *
 *      vg0_raid=/dev/md1
 *      vg0_md=md0
 *
 *
 * ==========================================================
 *
 * 同步机制：
 *
 * 每次执行：
 *
 * ① 清理历史RAID变量及md变量
 * ② 获取最新pvs数据
 * ③ 根据当前数据重新生成变量
 *
 *
 * 防止：
 *
 * 旧RAID删除后变量仍然存在
 *
 * ==========================================================
 */


// ==========================================================
// 1、获取响应
// ==========================================================

const res = pm.response.json();


// ==========================================================
// 2、清理历史RAID变量及md变量
//
// 必须放在前面
//
// 即使接口返回空数据，也需要清理旧变量。
// ==========================================================

for (let i = 0; i < 50; i++) {

    pm.moduleVariables.unset(`vg${i}_raid`);
    pm.moduleVariables.unset(`vg${i}_md`);

}


// 清理数量变量

pm.moduleVariables.unset("vg_raid_count");
pm.moduleVariables.unset("vg_md_count");



console.log("历史RAID变量及md变量清理完成。");



// ==========================================================
// 3、判断data是否存在
// ==========================================================

if (!res.data) {

    console.log("响应 data 为空，停止生成RAID变量。");

    return;

}



// ==========================================================
// 4、获取存储池名称
//
// 示例:
//
// name:
// vg0
//
// ==========================================================

const vgName = res.data.name;



// ==========================================================
// 5、获取pvs
//
// 示例:
//
// pvs:
//
// [
//     "/dev/md1"
// ]
//
// ==========================================================

const pvs = res.data.pvs;



// ==========================================================
// 6、判断pvs是否为空
//
// 注意：
// 此时历史变量已经清理
//
// 所以不会残留旧值。
// ==========================================================

if (!pvs || pvs.length === 0) {


    console.log("pvs为空，不生成新的RAID变量。");


    pm.moduleVariables.set(
        "vg_raid_count",
        0
    );


    console.log("====================================");
    console.log("RAID变量同步完成，无RAID设备。");
    console.log("====================================");


    // 注意：pvs为空时仍继续提取md
    // 不在此处return

}



// ==========================================================
// 7、生成RAID变量
//
// 当前规则:
//
// vg0_raid=/dev/md1
//
// 如果多个pvs:
//
// 只取第一个RAID设备
//
// ==========================================================

if (pvs && pvs.length > 0) {

    const raidVariableName = `${vgName}_raid`;


    pm.moduleVariables.set(
        raidVariableName,
        pvs[0]
    );


    console.log(
        `${raidVariableName} = ${pvs[0]}`
    );


    // 保存RAID数量

    pm.moduleVariables.set(
        "vg_raid_count",
        pvs.length
    );

}



// ==========================================================
// 8、提取 raidname（md设备名）
//
// 来源：
//
// res.data.volumes[].raidname[]
//
// 示例:
//
// volumes[0].raidname = ["md0"]
//
// 生成规则:
//
// vg0_md = md0
//
// 取所有卷中去重后的第一个raidname
//
// ==========================================================

const volumes = res.data.volumes;


if (!volumes || volumes.length === 0) {

    console.log("volumes为空，不生成md变量。");

    pm.moduleVariables.set(
        "vg_md_count",
        0
    );

} else {

    // 收集所有卷中的 raidname，去重

    const mdSet = new Set();

    for (const vol of volumes) {

        if (vol.raidname && vol.raidname.length > 0) {

            for (const md of vol.raidname) {
                mdSet.add(md);
            }

        }

    }


    if (mdSet.size === 0) {

        console.log("所有卷的raidname为空，不生成md变量。");

        pm.moduleVariables.set(
            "vg_md_count",
            0
        );

    } else {

        // 取第一个md设备名

        const mdName = [...mdSet][0];

        const mdVariableName = `${vgName}_md`;


        pm.moduleVariables.set(
            mdVariableName,
            mdName
        );


        console.log(
            `${mdVariableName} = ${mdName}`
        );


        // 保存md数量

        pm.moduleVariables.set(
            "vg_md_count",
            mdSet.size
        );

    }

}



// ==========================================================
// 9、输出日志
// ==========================================================

console.log("====================================");
console.log(`存储池：${vgName}`);
console.log(`RAID数量：${pvs ? pvs.length : 0}`);
console.log("RAID设备变量及md变量同步完成。");
console.log("====================================");

// GET /v2/storage/edit/pool/:uuid 后置脚本
// 按池名生成 {池名}_check_disk，空就删

const data = pm.response.json().data;

const freeDevices = (data.free_disk || [])
    .map(d => d.device);

console.log('池名:', data.name);
console.log('空闲磁盘:', freeDevices);

if (freeDevices.length > 0) {
    pm.environment.set(`${data.name}_check_disk`, freeDevices.join(','));
    console.log(`已设置 ${data.name}_check_disk = ${freeDevices.join(',')}`);
} else {
    pm.environment.unset(`${data.name}_check_disk`);
    console.log(`已删除 ${data.name}_check_disk`);
}

// ============================================================
// GET /v2/storage/create/pool 后置脚本
// 解析返回 → 写入模块变量 → 供后续 POST 创建存储池使用
// ------------------------------------------------------------
// 遵循 POSTMAN_SCRIPT_STANDARDS.md 中的强制规范：
//   1. 每次执行必须先清理旧的同前缀变量（动态扫描 cp_ 前缀）
//   2. 有值就 set，没值就 unset，不允许残留空字符串或 0
//   3. 磁盘变量按索引 cp_disk_N_* 铺开，不限数量（适配大盘位机器）
// ============================================================

const res = pm.response.json();
const data = res.data || res;

// ------------------------------------------------------------
// 小工具：有值就 set，否则 unset，避免残留空变量
// ------------------------------------------------------------
function setOrUnset(key, val) {
    if (val === undefined || val === null || val === '' || Number.isNaN(val)) {
        pm.moduleVariables.unset(key);
    } else {
        pm.moduleVariables.set(key, val);
    }
}

// ============================================================
// 0. 清理所有旧的 cp_ 变量（动态扫描，防止残留）
// ============================================================
const allModuleVars = pm.moduleVariables.toObject();
Object.keys(allModuleVars)
    .filter(k => k.startsWith('cp_'))
    .forEach(k => pm.moduleVariables.unset(k));

// ============================================================
// 1. 响应合法性校验
// ============================================================
pm.test('响应结构正确', () => {
    pm.expect(res).to.be.an('object');
    pm.expect(data).to.have.property('pool_info');
    pm.expect(data).to.have.property('free_disk');
    pm.expect(data.free_disk).to.be.an('array');
});

pm.test('至少存在一个空闲磁盘（POST disks 必填 ≥1 item）', () => {
    pm.expect(data.free_disk.length).to.be.above(0);
});

// ============================================================
// 2. 空闲磁盘列表 → 提取 name / 设备路径 / 类型 / 容量
// ============================================================
const freeDisks = (data.free_disk || []).map(d => ({
    label: `${d.name}(${d.device || ''}, ${d.capacity || ''})`,  // 展示：HDD1(/dev/sdg, 128 GB)
    value: (d.device || '').trim(),           // 设备路径：/dev/sdg（.trim 防 %20）
    name:  (d.name  || '').trim(),            // 盘位名：HDD1
    slot:  d.slot || 0,                       // 槽位号
    type:  d.type || '',                      // ssd / normal / nvme
    capacity: d.capacity || '',               // 容量文本：128 GB
    bytes: d.bytes?.value || 0,               // 容量字节数
    status: d.status || '',                   // 状态
}));

// ------------------------------------------------------------
// 2.1 汇总变量：仅列表 JSON 与总数，方便日志与用例判断
// ------------------------------------------------------------
if (freeDisks.length > 0) {
    pm.moduleVariables.set('cp_disk_list', JSON.stringify(freeDisks));
    pm.moduleVariables.set('cp_disk_count', freeDisks.length);
}

// ------------------------------------------------------------
// 2.2 按索引为每一块空闲磁盘生成独立变量（数量不限，几块生成几块）
//     命名规则：cp_disk_<索引>_<字段>，索引从 0 开始
//     大盘位 12/16/24 盘位机器同样按此规则扩展至 cp_disk_23_path
// ------------------------------------------------------------
freeDisks.forEach((d, i) => {
    setOrUnset(`cp_disk_${i}_path`,     d.value);       // /dev/sdg
    setOrUnset(`cp_disk_${i}_name`,     d.name);        // HDD1
    setOrUnset(`cp_disk_${i}_type`,     d.type);        // ssd / normal / nvme
    setOrUnset(`cp_disk_${i}_capacity`, d.capacity);    // 128 GB
    setOrUnset(`cp_disk_${i}_slot`,     d.slot);        // 1
});

// ============================================================
// 3. 新建存储池信息（本次创建成功后将生成的池）
// ============================================================
const poolInfo = data.pool_info || {};
setOrUnset('cp_new_pool_show_name',   poolInfo.show_name);       // ${storage,storagepool} 4
setOrUnset('cp_new_pool_sort',        poolInfo.sort);            // 4
setOrUnset('cp_new_pool_uuid',        poolInfo.uuid);            // 创建前一般为空
setOrUnset('cp_new_pool_description', poolInfo.description);
setOrUnset('cp_new_pool_compression', poolInfo.compression);

// 由 sort 推导下一个 vg 名（vgN = sort - 1，与存储池变量命名规则一致）
if (typeof poolInfo.sort === 'number' && poolInfo.sort >= 1) {
    pm.moduleVariables.set('cp_new_pool_vg_name', `vg${poolInfo.sort - 1}`);
} else {
    pm.moduleVariables.unset('cp_new_pool_vg_name');
}

// ============================================================
// 4. 调试输出
// ============================================================
console.log('==== 创建存储池资源一览 ====');
console.log(`空闲磁盘: ${freeDisks.length} 块`);
freeDisks.forEach((d, i) => {
    console.log(`  cp_disk_${i}_path=${d.value}, name=${d.name}, type=${d.type}, capacity=${d.capacity}`);
});
console.log(`新池: show_name=${poolInfo.show_name || '(未返回)'}, sort=${poolInfo.sort}, vg=${pm.moduleVariables.get('cp_new_pool_vg_name') || '?'}`);


// // 单盘 basic
// { "level": "basic", "disks": ["{{cp_disk_0_path}}"] }

// // 双盘 RAID1
// { "level": "raid1", "disks": ["{{cp_disk_0_path}}", "{{cp_disk_1_path}}"] }

// // 三盘 RAID5
// { "level": "raid5", "disks": ["{{cp_disk_0_path}}", "{{cp_disk_1_path}}", "{{cp_disk_2_path}}"] }

// // 四盘 RAID6/RAID10
// { "level": "raid6",  "disks": ["{{cp_disk_0_path}}", "{{cp_disk_1_path}}", "{{cp_disk_2_path}}", "{{cp_disk_3_path}}"] }
// { "level": "raid10", "disks": ["{{cp_disk_0_path}}", "{{cp_disk_1_path}}", "{{cp_disk_2_path}}", "{{cp_disk_3_path}}"] }

// // 大盘位 TRAID 全组（示例：12 盘）
// { "level": "traid", "disks": [
//     "{{cp_disk_0_path}}","{{cp_disk_1_path}}","{{cp_disk_2_path}}","{{cp_disk_3_path}}",
//     "{{cp_disk_4_path}}","{{cp_disk_5_path}}","{{cp_disk_6_path}}","{{cp_disk_7_path}}",
//     "{{cp_disk_8_path}}","{{cp_disk_9_path}}","{{cp_disk_10_path}}","{{cp_disk_11_path}}"
// ] }

// // 跳选（负面用例：仅选 0/2/4 盘）
// { "level": "raid5", "disks": ["{{cp_disk_0_path}}", "{{cp_disk_2_path}}", "{{cp_disk_4_path}}"] }

// ============================================================
// GET /v2/disk/list 后置脚本（示例路径，请按实际接口路径调整注释）
// 解析返回 → 写入模块变量 → 供后续接口引用磁盘路径
// ------------------------------------------------------------
// 遵循 POSTMAN_SCRIPT_STANDARDS.md 中的强制规范：
//   1. 每次执行必须先清理旧的同前缀变量
