// 提取所有支持热备的存储池 vgs 名称，
// 生成 hs{N}_vg（如 hs1_vg = vg0），供创建热备盘使用
// ------------------------------------------------------------
// POST /v2/hotsparedisk/CreateHotSpareDisk 请求体示例：
//   { "devices": ["{{hs1_device}}"], "raids": ["{{hs1_vg}}"] }
// ============================================================

const res = pm.response.json();
const data = res.data || res;

function setOrUnset(key, val) {
    if (val === undefined || val === null || val === '' || Number.isNaN(val)) {
        pm.moduleVariables.unset(key);
    } else {
        pm.moduleVariables.set(key, val);
    }
}

// ============================================================
// 0. 清理所有旧的 hs{N}_vg 变量
// ============================================================
const allModuleVars = pm.moduleVariables.toObject();
Object.keys(allModuleVars)
    .filter(k => /^hs\d+_vg$/.test(k))
    .forEach(k => pm.moduleVariables.unset(k));

// ============================================================
// 1. 标准化为数组
// ============================================================
let pools;
if (Array.isArray(data)) {
    pools = data;
} else if (data && typeof data === 'object') {
    pools = [data];
} else {
    pools = [];
}

if (pools.length === 0) {
    console.log('无支持热备的存储池，所有 hs_vg 变量已清空');
    pm.moduleVariables.set('hs_vg_count', 0);
    return;
}

// ============================================================
// 2. 提取每个池的 vgs 名称，按数组顺序从 1 起编号
// ============================================================
const vgNames = [];
pools.forEach(p => {
    const vgName = (p.vgs || '').trim();
    if (vgName) vgNames.push(vgName);
});

if (vgNames.length === 0) {
    console.log('无有效 vgs 名称，所有 hs_vg 变量已清空');
    pm.moduleVariables.set('hs_vg_count', 0);
    return;
}

// 按原数组顺序写入 hs{N}_vg（N 从 1 起）
vgNames.forEach((name, i) => {
    const idx = i + 1;
    pm.moduleVariables.set(`hs${idx}_vg`, name);
    console.log(`hs${idx}_vg = ${name}`);
});

pm.moduleVariables.set('hs_vg_count', vgNames.length);
pm.moduleVariables.set('hs_vg_list', JSON.stringify(vgNames));

// ============================================================
// 3. 调试输出
// ============================================================
console.log(`==== 热备存储池同步结果 ====`);
console.log(`支持热备的存储池: ${vgNames.length} 个 → ${vgNames.join(', ')}`);

const updatedVars = pm.moduleVariables.toObject();
const hsVgVars = Object.keys(updatedVars)
    .filter(k => /^hs\d+_vg$/.test(k))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));

if (hsVgVars.length > 0) {
    console.log('---------- hs{N}_vg 明细 ----------');
    hsVgVars.forEach(k => console.log(`${k} = ${updatedVars[k]}`));
}
console.log('=======================================');

// ============================================================
// GET /v2/hotsparedisk/GetHotSpareList 后置脚本
// 提取已有热备盘的 device 和 device_name，
// 生成 hsp{N}_device 和 hsp{N}_blk（N 从 1 起）
// ------------------------------------------------------------
// hsp{N}_device → POST /v2/hotsparedisk/DelHotSpare（删除热备盘）
// hsp{N}_blk    → POST /v2/hotsparedisk/ModifyArray（修改关联阵列）
// ============================================================

const res = pm.response.json();
const data = res.data || res;

function setOrUnset(key, val) {
    if (val === undefined || val === null || val === '' || Number.isNaN(val)) {
        pm.moduleVariables.unset(key);
    } else {
        pm.moduleVariables.set(key, val);
    }
}

// ============================================================
// 0. 清理所有旧的 hsp 变量
// ============================================================
const allModuleVars = pm.moduleVariables.toObject();
Object.keys(allModuleVars)
    .filter(k => /^hsp\d+_/.test(k))
    .forEach(k => pm.moduleVariables.unset(k));

// ============================================================
// 1. 标准化为数组
// ============================================================
let items;
if (Array.isArray(data)) {
    items = data;
} else if (data && typeof data === 'object') {
    items = [data];
} else {
    items = [];
}

if (items.length === 0) {
    console.log('当前无已有热备盘，所有 hsp 变量已清空');
    pm.moduleVariables.set('hsp_count', 0);
    return;
}

// ============================================================
// 2. 提取 device 和 device_name，按数组顺序从 1 起编号
// ============================================================
items.forEach((item, i) => {
    const idx = i + 1;
    setOrUnset(`hsp${idx}_device`, (item.device || '').trim());
    setOrUnset(`hsp${idx}_blk`,    (item.device_name || '').trim());
    console.log(`hsp${idx}_device = ${item.device}, hsp${idx}_blk = ${item.device_name} (${item.name || ''})`);
});

pm.moduleVariables.set('hsp_count', items.length);

// ============================================================
// 3. 调试输出
// ============================================================
console.log(`==== 已有热备盘同步结果 ====`);
console.log(`已有热备盘: ${items.length} 个`);

const updatedVars = pm.moduleVariables.toObject();
const hspVars = Object.keys(updatedVars)
    .filter(k => /^hsp\d+_device$/.test(k))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));

if (hspVars.length > 0) {
    console.log('---------- hsp{N} 明细 ----------');
    hspVars.forEach(k => {
        const n = k.match(/hsp(\d+)_device/)[1];
        console.log(`${k} = ${updatedVars[k]}`);
        console.log(`hsp${n}_blk  = ${updatedVars[`hsp${n}_blk`] || '(无)'}`);
    });
} else {
    console.log('(无)');
}
console.log('=======================================');

// ============================================================
// GET /v2/hotsparedisk/GetAvailableDiskList 后置脚本
// 遍历返回的空闲磁盘列表，反查已存在的 disk{N}_device，
// 生成 hs{N}_device / hs{N}_name（按热备可用顺序编号，从 1 起）
// ------------------------------------------------------------
// 依赖：必须先执行 GET /v2/disk/GetDiskOption（脚本 11）
// ============================================================

const res = pm.response.json();
const data = res.data || res;

function setOrUnset(key, val) {
    if (val === undefined || val === null || val === '' || Number.isNaN(val)) {
        pm.moduleVariables.unset(key);
    } else {
        pm.moduleVariables.set(key, val);
    }
}

// ============================================================
// 0. 清理所有旧的热备变量
// ============================================================
const allModuleVars = pm.moduleVariables.toObject();
Object.keys(allModuleVars)
    .filter(k => /^hs\d+_/.test(k))
    .forEach(k => pm.moduleVariables.unset(k));

// ============================================================
// 1. 标准化为数组
// ============================================================
let disks;
if (Array.isArray(data)) {
    disks = data;
} else if (data && typeof data === 'object') {
    disks = [data];
} else {
    disks = [];
}

if (disks.length === 0) {
    console.log('无可用于热备的空闲磁盘，所有 hs 变量已清空');
    pm.moduleVariables.set('hs_disk_count', 0);
    return;
}

// ============================================================
// 2. 遍历标记，按热备可用顺序生成 hs{N}_device / hs{N}_name
// ============================================================
let hsIndex = 0;
disks.forEach(d => {
    const devPath = (d.device || '').trim();
    if (!devPath) return;
    hsIndex++;
    const idx = hsIndex;  // 从 1 起
    setOrUnset(`hs${idx}_device`, devPath);
    setOrUnset(`hs${idx}_name`,   (d.name || '').trim());
    console.log(`hs${idx}_device = ${devPath} (${d.name || ''})`);
});

pm.moduleVariables.set('hs_disk_count', hsIndex);

// ============================================================
// 3. 调试输出
// ============================================================
console.log(`==== 热备磁盘同步结果 ====`);
console.log(`可热备空闲磁盘: ${hsIndex} 块`);

const updatedVars = pm.moduleVariables.toObject();
const hsDiskVars = Object.keys(updatedVars)
    .filter(k => /^hs\d+_device$/.test(k))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));

if (hsDiskVars.length > 0) {
    console.log('---------- hs{N} 变量明细 ----------');
    hsDiskVars.forEach(k => {
        const n = k.match(/hs(\d+)_device/)[1];
        console.log(`${k} = ${updatedVars[k]}`);
        console.log(`hs${n}_name  = ${updatedVars[`hs${n}_name`] || '(无)'}`);
    });
} else {
    console.log('(无)');
}
console.log('=======================================');

